import { ChatSectionRef } from '../types/chat';
import PasswordForm from '../components/PasswordForm';
import ChatSection from '../components/ChatSection';

const Index = () => {
  const [language, setLanguage] = useState<'de' | 'en'>('de');
  const [showChat, setShowChat] = useState(false);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatRef = useRef<ChatSectionRef>(null);

  const handleHintClick = () => {
    setShowChat(true);

    // Focus the chat input after a short delay to ensure the component is mounted
    setTimeout(() => {
      chatRef.current?.focus();
    }, 100);
  };

  const handleLanguageToggle = () => {
    if (isChatLoading) return;

    setShowChat(true);
    setLanguage(language === 'de' ? 'en' : 'de');
    const message = language === 'de' 
      ? 'please translate this page to English'
      : 'Seite bitte auf Deutsch übersetzen';

    // Send the translation request message to chat
    setTimeout(() => {
      chatRef.current?.sendMessage(message);
    }, 100);
  };

  // Handle loading state changes from ChatSection
  const handleChatLoadingChange = (isLoading: boolean) => {
    setIsChatLoading(isLoading);
  };

  return (
    <main id="puzzle" className="min-h-screen bg-gradient-to-br from-gray-900 via-black to-gray-900 flex flex-col items-center justify-center p-1" role="main" aria-label="Login and chat interface">
      <div className="w-full max-w-2xl">
        <PasswordForm
          language={language}
          onHintClick={handleHintClick}
          onLanguageToggle={handleLanguageToggle}
          isLoading={isChatLoading}
          aria-labelledby="form-title"
        />

        {showChat && (
          <section id="chat-section" aria-labelledby="chat-section" className="mt-4">
            <h2 id="chat-section" className="sr-only">Chat Section</h2>
            <ChatSection
              ref={chatRef}
              onLoadingChange={handleChatLoadingChange}
            />  
          </section>
        )}
      </div>
    </main>
  );
};

export default Index;/**
 * Utility for prefetching chat server to reduce cold start latency
 */

// The API endpoint URL for the chat function
const CHAT_API_URL = 'https://chat-598109592614.europe-west1.run.app';

/**
 * Creates a minimal loading indicator in the top right corner
 */
const createLoadingIndicator = (): HTMLElement => {
  const indicator = document.createElement('div');

  // Set positioning and appearance
  const position = { top: '10px', left: '10px' };

  Object.assign(indicator.style, {
    position: 'fixed',
    ...position,
    padding: '6px 12px',
    background: 'rgba(0, 0, 0, 0.7)',
    color: 'white',
    borderRadius: '4px',
    fontSize: '14px',
    fontFamily: 'system-ui, -apple-system, sans-serif',
    zIndex: '9999',
    transition: 'opacity 0.3s ease'
  });

  // Add it to the body
  document.body.appendChild(indicator);

  // Initialize countdown
  let secondsLeft = 60;

  // Function to update the text content
  function updateText() {
    indicator.textContent = `Chat server starting, please wait ${secondsLeft}s`;
  }

  // Set initial text
  updateText();

  // Function to update the countdown
  function updateCountdown() {
    secondsLeft--;
    updateText();

    if (secondsLeft < 0) {
      clearInterval(countdownInterval);
    }
  }

  // Set up interval for countdown
  const countdownInterval = setInterval(updateCountdown, 1000);

  // Store interval for cleanup
  (indicator as any)._intervals = [countdownInterval];

  return indicator;
};

/**
 * Removes the loading indicator with a fade-out effect
 */
const removeLoadingIndicator = (indicator: HTMLElement): void => {
  // Clear any intervals associated with the indicator
  if ((indicator as any)._intervals) {
    (indicator as any)._intervals.forEach((id: number) => clearInterval(id));
  }

  // Fade out effect
  indicator.style.opacity = '0';

  // Remove from DOM after fade completes
  setTimeout(() => {
    // Node removes itself
    indicator.remove();
  }, 300);
};

/**
 * Initiates a simple prefetch request to warm up the chat server
 * This helps reduce cold start latency for the first actual user interaction
 */
export const prefetchServer = async (): Promise<void> => {
  // Create loading indicator
  const indicator = createLoadingIndicator();

  try {
    console.log('Warming up chat server with prefetch request...');
    await fetch(CHAT_API_URL);
  } finally {
    // Remove the indicator when done (whether successful or not)
    removeLoadingIndicator(indicator);
  }
};

/**
 * Initiates prefetch request to warm up the chat server
 */
export const prefetchChat = async (): Promise<void> => {
  await prefetchServer();
};

// Wait for page to fully load before prefetching to avoid blocking initial render
if (document.readyState === 'complete') {
  // If already loaded (rare case), run immediately
  setTimeout(() => prefetchChat(), 0);
} else {
  // Otherwise wait for the 'load' event
  window.addEventListener('load', () => {
    // Add a small delay to ensure it happens after critical rendering
    setTimeout(() => prefetchChat(), 100);
  });
