      aria-label="Chat message history"
    >
      {messages.map((message) => (
        <div
          key={message.id}
          id={`message-${message.id}`}
          className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
          aria-label={`${message.sender === 'user' ? 'You' : 'Assistant'} said`}
        >
          <div
            className={`max-w-xs px-4 py-2 rounded-lg ${
              message.sender === 'user'
                ? 'bg-green-600 text-white'
                : 'bg-gray-700 text-gray-100'
            }`}
          >
            <p className="text-sm">
              {message.sender === 'model' && message.role && `${message.role}: `}{message.text}
            </p>
            <time 
              id={`message-time-${message.id}`}
              className="text-xs mt-1 opacity-60"
              dateTime={message.timestamp.toISOString()}
              aria-label={`Sent at ${message.timestamp.toLocaleTimeString()}`}
            >
              {message.timestamp.toLocaleTimeString()}
            </time>
          </div>
        </div>
      ))}

      {isLoading && (
        <div id="loading-message" className="flex justify-start" role="status" aria-live="assertive">
          <div className="bg-gray-700 text-gray-100 px-4 py-2 rounded-lg">
            <div className="flex items-center space-x-2">
              <Loader2 size={16} className="animate-spin" aria-hidden="true" />
              <span className="text-sm">{chatTranslations.typing}</span>
            </div>
          </div>
        </div>
      )}

      <div ref={messagesEndRef} aria-hidden="true" />
    </div>
  );
};

export default MessageList;import React, { useRef, useEffect, forwardRef, useImperativeHandle } from 'react';
import { useChat } from '../hooks/useChat';
import { ChatSectionRef } from '../types/chat';
import MessageList from './chat/MessageList';
import ChatInput from './chat/ChatInput';

interface ChatSectionProps {
  onLoadingChange?: (isLoading: boolean) => void;
}

const ChatSection = forwardRef<ChatSectionRef, ChatSectionProps>(({ onLoadingChange }, ref) => {
  const { messages, isLoading, sendMessage } = useChat();

  // Notify parent of loading state changes
  useEffect(() => {
    onLoadingChange?.(isLoading);
  }, [isLoading, onLoadingChange]);

  // Expose sendMessage globally for mcpTools
  React.useEffect(() => {
    window.__triggerChatMessage = sendMessage;
    return () => {
      if (window.__triggerChatMessage === sendMessage) {
        delete window.__triggerChatMessage;
      }
    };
  }, [sendMessage]);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    sendMessage,
    focus: () => {
      inputRef.current?.focus();
    }
  }));

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  return (
    <div id="chat-container" className="w-full mt-6" role="region" aria-label="Chat interface">
      <div id="chat-wrapper" className="bg-gray-900 rounded-lg border border-green-500/20 shadow-2xl" role="bot" aria-live="polite" aria-atomic="false">
        <header className="p-4 border-b border-gray-700" aria-labelledby="chat-title">
          <h3 id="chat-title" className="text-lg font-semibold text-green-400">Digitaler Mitarbeiter Chat</h3>
        </header>

        <MessageList 
          messages={messages} 
          isLoading={isLoading} 
          messagesEndRef={messagesEndRef} 
        />

        <ChatInput 
          onSendMessage={sendMessage} 
          isLoading={isLoading}
          inputRef={inputRef}
          aria-label="Chat message"
        />
      </div>
    </div>
  );
});

ChatSection.displayName = 'ChatSection';

export default ChatSection;import {useEffect, useState} from 'react';
import {chatTranslations, Message} from '../types/chat';
import mcpTools from '../utils/mcpTools';
// The API endpoint URL
const API_URL = 'https://chat-598109592614.europe-west1.run.app';

export const useChat = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const getCurrentRole = () => {
    return document.getElementById('role')?.getAttribute('value');
  };


  useEffect(() => {
    // Initialize chat with welcome message    
    const welcomeMessage: Message = {
      id: '0',
      text: chatTranslations.agentWelcome,
      sender: 'model',
      timestamp: new Date(),
      role: getCurrentRole()
    };

    setMessages([welcomeMessage]);
  }, []);

  const processMCPCalls = async (response: string): Promise<string> => {
    const { calls, cleanText } = mcpTools.extractMCPCalls(response);

    // Execute all MCP calls
    for (const call of calls) {
      try {
        await mcpTools.executeMCPCall(call);
      } catch (error) {
        console.error('Failed to execute MCP call:', error);
      }
    }

    return cleanText;
  };

  const callGeminiAPI = async (messageHistory: Message[]): Promise<string> => {

    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer 56e287b2-78ab-4ccb-a8cd-8113583058c3`,
        'X-Role': getCurrentRole()
      },
      body: JSON.stringify({
        messageHistory,
        htmlb64: btoa(unescape(encodeURIComponent(document.documentElement.outerHTML)))
      })
    });
    return response.text();
  };

  const handleAgentResponse = async (messageHistory: Message[]) => {
    setIsLoading(true);
    const role = getCurrentRole();

    try {
      const response = await callGeminiAPI(messageHistory);
      const processedResponse = await processMCPCalls(response);

      const agentMessage: Message = {
        id: (messageHistory.length + 1).toString(),
        text: processedResponse,
        sender: 'model',
        timestamp: new Date(),
        role
      };

      setMessages(prev => [...prev, agentMessage]);
    } catch (error: any) {
      console.error('Error in handleAgentResponse:', error);
      let errorMessage = chatTranslations.errorGeneric;

      if (error.status === 429) {
        errorMessage = chatTranslations.errorRateLimit;
      }

      const errorAgentMessage: Message = {
        id: (messageHistory.length + 1).toString(),
        text: errorMessage,
        sender: 'model',
        timestamp: new Date()
      };

      setMessages(prev => [...prev, errorAgentMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const sendMessage = (messageText: string, sender: "user" | "model" = 'user') => {
    // FIXME should have proper tool to invoke role change
    if (messageText.trim() === '' && sender === 'model') {
      handleAgentResponse(messages);
      return;
    }

    const userMessage: Message = {
      id: Math.random().toString(36).substring(2, 15),
      text: messageText,
      sender: sender,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    handleAgentResponse(newMessages);
  };

  return {
    messages,
    isLoading,
    sendMessage
  };
};interface MCPCall {
  tool: string;
  parameters: Record<string, any>;
}

interface MCPToolsHandler {
  extractMCPCalls: (text: string) => { calls: MCPCall[], cleanText: string };
  executeMCPCall: (call: MCPCall) => Promise<any>;
}

const mcpTools: MCPToolsHandler = {
  extractMCPCalls: (text: string) => {
    //console.log('Extracting MCP calls from text:', text);
    let hasCalls = false;
    // if text contains <mcp:browser_js_env_call or <mcp:page_inner_html_base64
    if (text.includes('<mcp:')) {
      hasCalls = true;
    }



    // Look for MCP tool calls in the format: <mcp:tool_name param1="value1" param2="value2" />
    const mcpRegex = /<mcp:(\w+)(?: (.*?))? \/>/g;
    const calls: MCPCall[] = [];
    let cleanText = text;

    let match;
    while ((match = mcpRegex.exec(text)) !== null) {
      const toolName = match[1];
      const paramString = match[2];

      // Parse parameters from the attribute string
      const parameters: Record<string, any> = {};
      // Using a regex with the 's' flag to handle multi-line parameter values
      const paramRegex = /(\w+)="([\s\S]*?)"/g;
      let paramMatch;
      while ((paramMatch = paramRegex.exec(paramString)) !== null) {
        parameters[paramMatch[1]] = paramMatch[2];
      }

      calls.push({
        tool: toolName,
        parameters
      });

      // Remove the MCP call from the text
      //cleanText = cleanText.replace(match[0], '🏗️').trim();
      cleanText = cleanText.replace(match[0], '').trim();
    }

    //console.log('Extracted MCP calls:', calls);
    if (hasCalls && calls.length <= 0) {
      throw new Error('No MCP calls found');
    }

    return { calls, cleanText };
  },

  executeMCPCall: async (call: MCPCall) => {
    //console.log('Executing MCP call:', call);

    switch (call.tool) {
      case 'browser_js_env_call':
        return eval(call.parameters.script);

      case 'page_outer_html_base64':
        if (typeof window !== 'undefined' && typeof window.__triggerChatMessage === 'function') {
          setTimeout(() => {
            window.__triggerChatMessage('', 'model');
          }, 700); // Trigger Chat sendMessage after a delay to ensure it appears after the agent's response

        }
        return null;

      default:
        console.warn(`Unknown MCP tool: ${call.tool}`);
        return null;
    }
  }
};

export default mcpTools;name: Deploy to GitHub Pages

on:
  push:
    branches: [ main ]  


  # Allows you to run this workflow manually from the Actions tab
  workflow_dispatch:

# Sets permissions of the GITHUB_TOKEN to allow deployment to GitHub Pages
permissions:
  contents: read
  pages: write
  id-token: write

# Allow only one concurrent deployment, skipping runs queued between the run in-progress and latest queued.
# However, do NOT cancel in-progress runs as we want to allow these production deployments to complete.
concurrency:
  group: "pages"
  cancel-in-progress: false

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '18'
      - name: Install dependencies
        run: npm ci
      - name: Build project
        # run: VITE_BASE_PATH="/${GITHUB_REPOSITORY#*/}/" npm run build
        # new domain
        run: npm run build
      - name: Upload artifact
        uses: actions/upload-pages-artifact@v3
        with:
          path: ./dist/
  deploy:
    needs: build
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - name: Deploy artifact
        id: deployment
        uses: actions/deploy-pages@v4import React, { useState } from 'react';

